public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (start == null || end == null) {
        throw new IllegalArgumentException("start and end cannot be null");
    }
    if (start.length != n || end.length != n) {
        throw new IllegalArgumentException("start and end must have length equal to n");
    }
    if (paths == null) {
        throw new IllegalArgumentException("paths cannot be null");
    }

    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> coordToKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // If start equals end, travel is possible
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            throw new IllegalArgumentException("Each path must have length 2*n");
        }
        int[] coordA = new int[n];
        int[] coordB = new int[n];
        System.arraycopy(path, 0, coordA, 0, n);
        System.arraycopy(path, n, coordB, 0, n);
        String keyA = coordToKey.apply(coordA);
        String keyB = coordToKey.apply(coordB);

        adj.computeIfAbsent(keyA, k -> new java.util.ArrayList<>()).add(keyB);
        adj.computeIfAbsent(keyB, k -> new java.util.ArrayList<>()).add(keyA);
    }

    // If start node has no connections, cannot travel
    if (!adj.containsKey(startKey)) {
        return "cannot be travelled";
    }

    // BFS to find connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        throw new IllegalArgumentException("Input date cannot be null");
    }
    // Normalize whitespace
    date = date.trim().replaceAll("\\s+", " ");
    try {
        java.time.format.DateTimeFormatter formatter =
                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.ENGLISH);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, formatter);
        String monthName = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format: " + date, e);
    }
}

public int[] twoSum(int[] nums, int target) {
