    if (n < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements");
    }
    java.util.Map<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) {
        int complement = target - nums[i];
        Integer prevIndex = map.get(complement);
        if (prevIndex != null) {
            return new int[]{prevIndex, i};
        }
        // Store the current number with its index
        map.put(nums[i], i);
    }
    // According to problem statement, there should always be a solution.
    // If not found, throw an exception to indicate unexpected input.
    throw new IllegalArgumentException("No two sum solution found");
}

public int search(int[] nums, int target) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
