    }
    int n = arr.length;
    int k = n / 20; // number of elements to trim from each side (5%)
    if (k == 0) {
        // If n < 20, no trimming is required
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / (double) n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
