    }
    return sum / (double) (n - 2 * k);
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (k <= 0) {
        throw new IllegalArgumentException("Divisor k must be positive");
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false; // cannot pair all elements
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // ensure non-negative remainder
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled k even case
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (edges == null || edges.length != n - 1) {
        throw new IllegalArgumentException("edges must contain n-1 elements");
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple must contain n elements");
    }

    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) {
            throw new IllegalArgumentException("each edge must have two nodes");
        }
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("edge node out of bounds");
        }
        adj[u].add(v);
        adj[v].add(u);
    }

    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;

    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    parent[0] = -2; // root marker

    while (top > 0) {
        int node = stack[--top];
        order[idx++] = node;
        for (int nei : adj[node]) {
            if (parent[nei] == -1) {
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
    }

    boolean[] hasAppleSub = new boolean[n];
    int time = 0;
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei : adj[node]) {
            if (parent[nei] == node) {
                if (hasAppleSub[nei]) {
                    has = true;
                    time += 2;
                }
            }
        }
        hasAppleSub[node] = has;
    }

    return time;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder(n);
    while (!map.isEmpty()) {
        // Step 1: pick smallest
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        sb.append(last);
        if (--entry.getValue() == 0) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue());
        }
        // Step 2: pick increasing sequence
        while (true) {
            java.util.Map.Entry<Character, Integer> nextEntry = map.higherEntry(last);
            if (nextEntry == null) {
                break;
            }
            last = nextEntry.getKey();
            sb.append(last);
            if (--nextEntry.getValue() == 0) {
                map.remove(last);
            } else {
                map.put(last, nextEntry.getValue());
            }
        }
        // Step 4: pick largest
        if (map.isEmpty()) {
            break;
        }
        entry = map.lastEntry();
        last = entry.getKey();
        sb.append(last);
        if (--entry.getValue() == 0) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue());
        }
        // Step 5: pick decreasing sequence
        while (true) {
            java.util.Map.Entry<Character, Integer> prevEntry = map.lowerEntry(last);
            if (prevEntry == null) {
                break;
            }
            last = prevEntry.getKey();
            sb.append(last);
            if (--prevEntry.getValue() == 0) {
                map.remove(last);
            } else {
                map.put(last, prevEntry.getValue());
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from current max down to 1 to avoid using updated values in same iteration
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1].isEmpty()) {
                continue;
            }
            for (int prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue;
        }
        int target = (int) (product / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return 0;
    }
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int costFromPrev1 = prev1 + cost[i - 1];
        int costFromPrev2 = prev2 + cost[i - 2];
        int current = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

