public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string s cannot be null");
    }
    if (k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    long totalCodes = 1L << k;
    if (totalCodes > Integer.MAX_VALUE) {
        // Too many codes to track with a boolean array; use a HashSet
        java.util.HashSet<Long> seen = new java.util.HashSet<>();
        long mask = 0L;
        long maskLimit = totalCodes - 1;
        for (int i = 0; i < n; i++) {
            int bit = s.charAt(i) - '0';
            mask = ((mask << 1) & maskLimit) | bit;
            if (i >= k - 1) {
                seen.add(mask);
                if (seen.size() == totalCodes) {
                    return true;
                }
            }
        }
        return seen.size() == totalCodes;
    } else {
        // Use a boolean array for efficiency
        int size = (int) totalCodes;
        boolean[] seen = new boolean[size];
        int mask = 0;
        int maskLimit = size - 1;
        for (int i = 0; i < n; i++) {
            int bit = s.charAt(i) - '0';
            mask = ((mask << 1) & maskLimit) | bit;
            if (i >= k - 1) {
                seen[mask] = true;
            }
        }
        for (boolean b : seen) {
            if (!b) {
                return false;
            }
        }
        return true;
    }
}

