public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int balance = 0;   // number of unmatched '('
    int insertions = 0; // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance > 0) {
                balance--; // match with an existing '('
            } else {
                // need to insert a '(' before this ')'
                insertions++;
            }
        } else {
            // invalid character, ignore or throw exception
            throw new IllegalArgumentException("String contains invalid character: " + c);
        }
    }
    // any remaining unmatched '(' need a ')' each
    return insertions + balance;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int m = (n - 1) / 2; // floor((n-1)/2)
    long ops = (long)(n - m - 1) * (m + 1);
    if (ops > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) ops;
}

