    }
    return dfs(0, new java.util.HashSet<>(), s);
}

public int minOperations(String[] logs) {
    if (logs == null) {
        throw new IllegalArgumentException("logs array cannot be null");
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            throw new IllegalArgumentException("log entry cannot be null");
        }
        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // stay in current folder, no change
                break;
            default:
                // Expect a folder name ending with '/'
                if (log.endsWith("/") && !log.equals("./") && !log.equals("../")) {
                    depth++;
                } else {
                    throw new IllegalArgumentException("invalid log entry: " + log);
                }
                break;
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n < 0) {
        throw new IllegalArgumentException("Length n must be non-negative");
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive");
    }
    char[] result = new char[n];
    // Initialize with 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // how much we need to add to reach k
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max we can add to this position
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

