public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    // Preserve sign and work with absolute value
    boolean negative = n < 0;
    long absVal = Math.abs((long) n);

    // Convert to string for easier processing
    String s = Long.toString(absVal);
    StringBuilder sb = new StringBuilder();

    int count = 0;
    // Build the string from the end, inserting dots after every three digits
    for (int i = s.length() - 1; i >= 0; i--) {
        sb.append(s.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Append negative sign if needed
    if (negative) {
        sb.append('-');
    }

    // Reverse to obtain the correct order
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    // Precompute adjacency matrix for perfect square sums
    boolean[][] adj = new boolean[n][n];
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    for (int i = 0; i * i <= maxSum; i++) {
        squares.add(i * i);
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && squares.contains(A[i] + A[j])) {
                adj[i][j] = true;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n + 1];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(memo[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int lastIdx) {
            if (mask == fullMask) return 1;
            int memoIdx = lastIdx + 1;
            if (memo[mask][memoIdx] != -1) return memo[mask][memoIdx];
            int count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (lastIdx != -1 && !adj[lastIdx][i]) continue;
                // Skip duplicates: if same value as previous and previous not used
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                count += applyAsInt(mask | (1 << i), i);
            }
            memo[mask][memoIdx] = count;
            return count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top >= 0) {
        int height = heights[stack[top--]];
        int width = (top == -1) ? n : n - stack[top] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int s = 0; s < m + n - 1; s++) {
        int row, col;
        if (s < m) {
            row = s;
            col = 0;
        } else {
            row = m - 1;
            col = s - (m - 1);
        }
        if (s % 2 == 0) {
            // even diagonal: go from bottom to top (row--, col++)
            while (row >= 0 && row < m && col >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            // odd diagonal: go from top to bottom (row++, col--)
            while (row >= 0 && row < m && col >= 0 && col < n) {
                result[idx++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Extract coordinates
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check for duplicate points
    if ((x1 == x2 && y1 == y2) || (x1 == x3 && y1 == y3) || (x2 == x3 && y2 == y3)) {
        return false;
    }

    // Compute cross product to check collinearity
    long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int n = s.length();
    if (n == 0) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < n; i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

